package com.fintrack.khmtomnenh.company.controller; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.company.dto.CompanyDto; import com.fintrack.khmtomnenh.company.entity.Company; import com.fintrack.khmtomnenh.company.service.CompanyService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/companies") @RequiredArgsConstructor public class CompanyController {private final CompanyService s; @GetMapping public List<Company> list(@AuthenticationPrincipal Auth a){return s.list(a);} @GetMapping("/{id}") public Company get(@PathVariable Long id){return s.get(id);} @PostMapping @PreAuthorize("hasRole('SUPPLIER')") public ResponseEntity<Company> create(@Valid @RequestBody CompanyDto d,@AuthenticationPrincipal Auth a){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(d,a));} @PutMapping("/{id}") @PreAuthorize("hasRole('SUPPLIER')") public Company update(@PathVariable Long id,@Valid @RequestBody CompanyDto d,@AuthenticationPrincipal Auth a){return s.update(id,d,a);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('SUPPLIER')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id,@AuthenticationPrincipal Auth a){s.delete(id,a);} }
